import { Component, h, Prop, Event, EventEmitter, Host, Element } from '@stencil/core';
import classnames from 'classnames';
import { TagColor, TagSize, TagVariant } from './types';
import { registerPluginManager } from '@src/shared/unclassified/plugin';
import { sendActionTracking } from '@src/shared/unclassified/tracking';
import { KsIconCloseSmall, KsIconDragItem } from '@fe-infra/keystone-icons-stencil';

const prefix = 'tag';

const VariantMap = {
  info: 'primary',
  new: 'support',
  neutral: 'neutral',
  success: 'success',
  error: 'error',
  warning: 'warning',
};

const COLOR_TYPES = ['neutral', 'primary', 'success', 'warning', 'error', 'support'];

function resolveColorStyles(color?: TagColor) {
  if (!color) {
    // TODO fallback to legacy @Prop() variant
    return {
      backgroundColor: '',
      color: '',
    };
  }

  let colorType: string | null = null;

  if (COLOR_TYPES.includes(color as TagColor)) {
    colorType = color as TagColor;
  } else {
    const match = color.match(/var\(--ks-color-([a-z]+)-/)?.[1];
    if (match) {
      if (COLOR_TYPES.includes(match)) {
        colorType = match;
      }
    }
  }

  return {
    '--ks-internal-tag-bg-color': colorType ? `var(--ks-color-${colorType}-surface2)` : color,
    color: colorType ? `var(--ks-color-${colorType}-onSurface)` : `var(--ks-color-neutral-onSurface)`,
  };
}

/**
 * @slot default - Tag label or custom content rendered inside the tag.
 * @part base - The base container of the component.
 * @part closeIcon - The close icon element.
 */
@Component({
  tag: 'ks-tag',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsTag {
  @Element() el!: HTMLKsTagElement;
  /** Variant style of the tag. Can be one of the following values: `"info"`, `"new"`, `"neutral"`, `"success"`, `"error"`, `"warning"`. */
  @Prop() variant: TagVariant = 'neutral';
  /** Color style of the tag. Can be one of the `"primary"`, `"support"`, `"neutral"`, `"success"`, `"error"`, `"warning"` or any Keystone color token like `var(--ks-color-neutral-surface3)`. */
  @Prop() color?: TagColor;
  /**  Size of the tag. Can be `"sm"`, `"md"` or `"lg"`. */
  @Prop() size?: TagSize = 'md';
  /** Indicates the tag is interactive. When `true`, the tag will have hover and active styles. */
  @Prop() interactive?: boolean;
  /** Indicates whether the tag is closeable. When `true`, a close button will appear on the tag. */
  @Prop() closeable?: boolean;
  /** Indicates whether the tag is disabled. When `true`, the tag is not interactive, clickable and closeable. */
  @Prop() disabled?: boolean;

  /**  Indicates whether the tag shows a drag handle. Please note that this controls the visual element but not the drag behavior. */
  @Prop() showDragHandle = false;
  /** If `true`, this property adds an KsStatusDot (a dot) to the tag. */
  @Prop() showStatusDot?: boolean;

  /** Force the button to stay in active style. It would be useful in scenarios like indicating which button triggered the KsPopover. */
  @Prop() forceActive = false;

  /**Custom event triggered when the tag's close button is clicked. This event can be used to execute additional actions when the tag is closed. */
  @Event({ bubbles: false, composed: false }) ksClose!: EventEmitter;

  constructor() {
    registerPluginManager(this.el);
  }

  private handleClose = (event: Event) => {
    if (!this.closeable || this.disabled) return;

    event.stopPropagation();
    this.ksClose.emit(event);
    sendActionTracking(this.el, { eventType: 'close' });
  };

  private preventClickIfDisabled = (event: Event) => {
    if (this.disabled) {
      event.stopPropagation();
      event.preventDefault();
    }
  };

  render() {
    const variantMapped = VariantMap[this.variant as keyof typeof VariantMap];
    const className = classnames(`${prefix}`, `${prefix}--${variantMapped}`, `${prefix}--${this.size}`, {
      [`${prefix}--interactive`]: this.interactive,
      [`${prefix}--disabled`]: this.disabled,
      [`${prefix}--closeable`]: this.closeable,
      [`${prefix}--force-active`]: this.forceActive,
    });
    const iconSize = this.size === 'sm' ? '14' : '16';

    return (
      <Host class="KsTag" aria-disabled={this.disabled ? 'true' : undefined} onClick={this.preventClickIfDisabled}>
        <div class={className} part="base" style={resolveColorStyles(this.color)}>
          {this.showStatusDot && <div class={'status-dot'} />}

          {this.showDragHandle && (
            <div class={`${prefix}-drag-icon`}>
              <KsIconDragItem size={iconSize}></KsIconDragItem>
            </div>
          )}

          <slot name="prefix"></slot>

          <div class={`${prefix}__content`}>
            <slot></slot>
          </div>
          {this.closeable && (
            <div
              class={`${prefix}__close-icon`}
              onClick={this.handleClose}
              part="closeIcon"
              data-testid="ks-tag-index-4ruw4p"
            >
              <KsIconCloseSmall size={iconSize} />
            </div>
          )}
        </div>
      </Host>
    );
  }
}
